const names=["document","names","name_alternative","unit","catalogue_value","value_element","product_group","product_class","class_required_property","class_optional_property","product_series","series_property","product","parameter_domain","domain_allowed_value","product_variant","variant_parameter","property_value","variant_property","product_static_property","product_index","index_tag","property_definition","accessory_group","accessory","composition_group","composition","descriptive_object","dictionary_subject","dictionary_relationship","dictionary_property","property_subject","value_constraint","constraint_allowed","controlled_list","controlled_value","controlled_context","geometry_object","geometry_node","geometry_child","primitive_parameter","space","surface","port","geometry_binding","primitive_kind","primitive_kind_parameter","selection_constraint","part_number_row","part_number_cell","part_number_input","extension_entry","extension_value","extension_element","extension_member"];
test("ISO16757 hand-authored full semantic DDL parses in independent SQLite",async()=>{const engine=new Database(":memory:",{safeIntegers:true});engine.exec("PRAGMA application_id=1397576526;PRAGMA user_version=1;"+schema);expect((engine.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY rowid").all()as{name:string}[]).map(r=>r.name)).toEqual(names.map(n=>"iso16757_"+n));expect(engine.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(engine.query("SELECT name FROM sqlite_schema WHERE type='index'").all()).toEqual([]);expect((await importSqliteDatabase(engine.serialize())).tables.map(t=>t.name)).toEqual(names.map(n=>"iso16757_"+n));for(const table of["value_element","geometry_child","extension_element","extension_member"]){const keys=engine.query("PRAGMA foreign_key_list(iso16757_"+table+")").all()as{table:string}[];expect(keys.length).toBe(2)}engine.close()});
import fixture from"../🧫️fixtures/🔣️.json";
import{iso16757SnapshotToSqliteDatabase as project,iso16757SnapshotFromSqliteDatabase as restore,type Iso16757SqliteSnapshot,type Iso16757SqliteValue,type Iso16757SqliteExtension}from"../🟦️.ts";
import{exportSqliteDatabase,type SqliteDatabase,type SqliteValue}from"../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🟦️.ts";
function owned(v:unknown,word:bigint):unknown{if(v===0.5)return{bits:word};if(Array.isArray(v))return v.map(a=>owned(a,word));if(v!==null&&typeof v==="object")return Object.fromEntries(Object.entries(v).map(([k,a])=>[k,owned(a,word)]));return v}
function extension(v:any):Iso16757SqliteExtension{switch(v.kind){case"Null":return{kind:"Null"};case"Boolean":return{kind:v.kind,value:v.value};case"Integer":case"Unsigned":return{kind:v.kind,value:BigInt(v.value)};case"Float":return{kind:v.kind,value:{bits:BigInt("0x"+v.bits)}};case"Text":return{kind:v.kind,value:v.value};case"Bytes":return{kind:v.kind,value:Uint8Array.from((v.hex.match(/../g)as string[]).map(s=>parseInt(s,16)))};case"Array":return{kind:v.kind,items:v.items.map(extension)};case"Object":return{kind:v.kind,members:v.members.map((a:any)=>({key:a.key,value:extension(a.value)}))};default:throw Error("neutral extension")}}
function value(v:any):Iso16757SqliteValue{v.kind=v.kind[0].toUpperCase()+v.kind.slice(1);if(v.kind==="Integer")v.value=BigInt(v.value);if(v.kind==="List")v.items=v.items.map(value);return v}
function node(v:any):any{if(v===null)return null;v.node=v.node[0].toUpperCase()+v.node.slice(1);if(v.node==="Primitive")v.parameters=new Map(Object.entries(v.parameters));if(v.node==="Transform")v.child=node(v.child);if(v.node==="Boolean")v.children=v.children.map(node);return v}
function snapshot(word=0x3fe0000000000000n):Iso16757SqliteSnapshot{const s:any=owned(fixture.snapshot,word);for(const a of s.catalogue.productSeries)a.sharedPropertyValues=new Map(Object.entries(a.sharedPropertyValues).map(([k,v])=>[k,value(v)]));for(const a of s.catalogue.products){for(const d of a.parameterDomains){d.allowedValues=d.allowedValues.map(value);if(d.defaultValue!==null)d.defaultValue=value(d.defaultValue)}for(const v of a.variants){v.parameterValues=new Map(Object.entries(v.parameterValues).map(([k,v])=>[k,value(v)]));for(const p of v.propertyValues)p.value=value(p.value)}for(const p of a.staticProperties)p.value=value(p.value)}s.catalogue.accessories=new Map(Object.entries(s.catalogue.accessories));s.catalogue.compositions=new Map(Object.entries(s.catalogue.compositions));s.catalogue.extensions.fields=new Map(Object.entries(s.catalogue.extensions.fields).map(([k,v])=>[k,{kind:"Text",value:v}]));s.catalogue.extensions.fields.set("typedTree",extension(fixture.extensionCases));s.geometry.objects=new Map(Object.entries(s.geometry.objects).map(([k,v]:[string,any])=>{v.shape=node(v.shape);v.symbolic=node(v.symbolic);v.parameterBindings=new Map(Object.entries(v.parameterBindings));return[k,v]}));for(const v of s.selection.constraints)v.value=value(v.value);s.partNumberInputs=new Map(Object.entries(s.partNumberInputs).map(([k,v])=>[k,value(v)]));s.partNumberRule.kind=s.partNumberRule.kind[0].toUpperCase()+s.partNumberRule.kind.slice(1);if(s.partNumberRule.kind==="Table")s.partNumberRule.rows=s.partNumberRule.rows.map((r:any)=>new Map(Object.entries(r)));s.scriptLimits.timeoutMs=BigInt(s.scriptLimits.timeoutMs);return s}
type MutableDatabase={tables:{name:string;sql:string;rows:{rowid:bigint;values:SqliteValue[]}[]}[]};
function editable(d:SqliteDatabase):MutableDatabase{return structuredClone(d)as MutableDatabase}
test("ISO16757 complete neutral catalogue dictionary geometry and extension entities",async()=>{const s=snapshot(),d=await project(s);expect(d.tables.length).toBe(55);for(const t of d.tables)expect(t.rows.length).toBeGreaterThan(0);expect(await restore(d)).toEqual(s);const engine=Database.deserialize(await exportSqliteDatabase(d),{safeIntegers:true});expect(engine.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(engine.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(engine.query("SELECT quantity FROM iso16757_composition").get()).toEqual({quantity:4294967295n});expect(engine.query("SELECT length,mass FROM iso16757_unit LIMIT 1").get()).toEqual({length:-128n,mass:127n});engine.query("UPDATE iso16757_document SET status='independent 日本'").run();const expected=snapshot();expected.catalogue.metadata.lifecycle.status="independent 日本";expect(await restore(await importSqliteDatabase(engine.serialize()))).toEqual(expected);engine.close()});
test("quick::ISO16757 value geometry extension identity order width and inactive fields refuse",async()=>{const d=await project(snapshot());for(const[table,index,value]of[["value_element",1,999999n],["geometry_child",1,999999n],["geometry_child",2,999999n],["unit",2,128n],["unit",3,-129n],["document",21,4294967296n],["document",23,-1n],["catalogue_value",2,2n],["document",17,"inactive"]]as const){const bad=editable(d);bad.tables.find(t=>t.name==="iso16757_"+table)!.rows[0]!.values[index]=value;await expect(restore(bad)).rejects.toThrow()}const cycle=editable(d),row=cycle.tables.find(t=>t.name==="iso16757_geometry_child")!.rows[0]!;row.values[3]=row.values[1]!;await expect(restore(cycle)).rejects.toThrow();const alias=editable(d),children=alias.tables.find(t=>t.name==="iso16757_geometry_child")!.rows;children[1]!.values[3]=children[0]!.values[3]!;await expect(restore(alias)).rejects.toThrow();const extra=snapshot()as Iso16757SqliteSnapshot&{opaque:string};extra.opaque="refused";await expect(project(extra)).rejects.toThrow();const cyclic=snapshot();const v:Iso16757SqliteValue={kind:"List",items:[]};v.items.push(v);cyclic.partNumberInputs.set("cycle",v);await expect(project(cyclic)).rejects.toThrow("cyclic")},30000);
test("ISO16757 domain controls pre-cancel and reject oversized complete models",async()=>{const s=snapshot(),d=await project(s);await expect(project(s,{maxRows:1})).rejects.toThrow();await expect(project(s,{maxValueBytes:16})).rejects.toThrow();await expect(restore(d,{maxValueBytes:16})).rejects.toThrow();const cancel=new AbortController();cancel.abort();await expect(project(s,{signal:cancel.signal})).rejects.toThrow();await expect(restore(d,{signal:cancel.signal})).rejects.toThrow();s.catalogue.metadata.lifecycle.status="地".repeat(40000);const large=new AbortController();let observed=false;await expect(project(s,{signal:large.signal,onProgress:p=>{if(p.phase==="projectSnapshot"&&p.completed>0){observed=true;large.abort()}}})).rejects.toThrow();expect(observed).toBe(true)});
