const names=["document","names","name_alternative","unit","catalogue_value","value_element","product_group","product_class","class_required_property","class_optional_property","product_series","series_property","product","parameter_domain","domain_allowed_value","product_variant","variant_parameter","property_value","variant_property","product_static_property","product_index","index_tag","property_definition","accessory_group","accessory","composition_group","composition","descriptive_object","dictionary_subject","dictionary_relationship","dictionary_property","property_subject","value_constraint","constraint_allowed","controlled_list","controlled_value","controlled_context","geometry_object","geometry_node","geometry_child","primitive_parameter","space","surface","port","geometry_binding","primitive_kind","primitive_kind_parameter","selection_constraint","part_number_row","part_number_cell","part_number_input","extension_entry","extension_value","extension_element","extension_member"];
test("ISO16757 hand-authored full semantic DDL parses in independent SQLite",async()=>{const engine=new Database(":memory:",{safeIntegers:true});engine.exec("PRAGMA application_id=1397576526;PRAGMA user_version=1;"+schema);expect((engine.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY rowid").all()as{name:string}[]).map(r=>r.name)).toEqual(names.map(n=>"iso16757_"+n));expect(engine.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(engine.query("SELECT name FROM sqlite_schema WHERE type='index'").all()).toEqual([]);expect((await importSqliteDatabase(engine.serialize())).tables.map(t=>t.name)).toEqual(names.map(n=>"iso16757_"+n));for(const table of["value_element","geometry_child","extension_element","extension_member"]){const keys=engine.query("PRAGMA foreign_key_list(iso16757_"+table+")").all()as{table:string}[];expect(keys.length).toBe(2)}engine.close()});
import fixture from"../🧫️fixtures/🔣️.json";
import{iso16757SnapshotToSqliteDatabase as project,iso16757SnapshotFromSqliteDatabase as restore,type Iso16757SqliteSnapshot,type Iso16757SqliteValue,type Iso16757SqliteExtension}from"../🟦️.ts";
import{exportSqliteDatabase,type SqliteDatabase,type SqliteValue}from"../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🟦️.ts";
function owned(v:unknown,word:bigint):unknown{if(v===0.5)return{bits:word};if(Array.isArray(v))return v.map(a=>owned(a,word));if(v!==null&&typeof v==="object")return Object.fromEntries(Object.entries(v).map(([k,a])=>[k,owned(a,word)]));return v}
function extension(v:any):Iso16757SqliteExtension{switch(v.kind){case"Null":return{kind:"Null"};case"Boolean":return{kind:v.kind,value:v.value};case"Integer":case"Unsigned":return{kind:v.kind,value:BigInt(v.value)};case"Float":return{kind:v.kind,value:{bits:BigInt("0x"+v.bits)}};case"Text":return{kind:v.kind,value:v.value};case"Bytes":return{kind:v.kind,value:Uint8Array.from((v.hex.match(/../g)as string[]).map(s=>parseInt(s,16)))};case"Array":return{kind:v.kind,items:v.items.map(extension)};case"Object":return{kind:v.kind,members:v.members.map((a:any)=>({key:a.key,value:extension(a.value)}))};default:throw Error("neutral extension")}}
function value(v:any):Iso16757SqliteValue{v.kind=v.kind[0].toUpperCase()+v.kind.slice(1);if(v.kind==="Integer")v.value=BigInt(v.value);if(v.kind==="List")v.items=v.items.map(value);return v}
function node(v:any):any{if(v===null)return null;v.node=v.node[0].toUpperCase()+v.node.slice(1);if(v.node==="Primitive")v.parameters=new Map(Object.entries(v.parameters));if(v.node==="Transform")v.child=node(v.child);if(v.node==="Boolean")v.children=v.children.map(node);return v}
